import { Agent, routeAgentRequest } from 'agents';

// Runs one submitted snippet. Lives as a dynamic agent (facet) of a Chat
// instance, with its own SQLite storage and no wrangler binding.
export class Sandbox extends Agent {
  async evaluate(code) {
    return `got ${code.length} chars`;
  }
}

export class Chat extends Agent {
  // Sandboxes are only reachable through this Chat instance's RPC calls,
  // never via external /sub/sandbox/{jobId} URLs.
  async onBeforeSubAgent() {
    return new Response('Not found', { status: 404 });
  }

  async onMessage(connection, message) {
    const text = String(message);

    const tryMatch = text.match(/^try\s+(\S+)\s+([\s\S]*)$/);
    if (tryMatch) {
      const [, jobId, code] = tryMatch;
      try {
        const sandbox = await this.dynamicAgents.get(Sandbox, jobId);
        const result = await sandbox.evaluate(code);
        connection.send(`${jobId}: ${result}`);
      } catch (err) {
        connection.send(`${jobId}: error: ${err?.message ?? err}`);
      }
      return;
    }

    const cancelMatch = text.match(/^cancel\s+(\S+)\s*$/);
    if (cancelMatch) {
      const [, jobId] = cancelMatch;
      // abort() stops the child immediately but preserves its storage;
      // delete() would wipe it.
      this.dynamicAgents.abort(Sandbox, jobId, new Error(`job ${jobId} cancelled`));
      connection.send(`${jobId}: cancelled`);
      return;
    }

    connection.send(`echo: ${text}`);
  }
}

export default {
  async fetch(request, env) {
    return (await routeAgentRequest(request, env)) ?? new Response('Not found', { status: 404 });
  },
};

import { Agent, routeAgentRequest } from 'agents';

// Builds the user's data export and returns its download URL. Slow: it can take a minute for big accounts.
async function buildExport(agentName) {
  await new Promise((resolve) => setTimeout(resolve, 5000));
  return `https://exports.example.com/${encodeURIComponent(agentName)}/${Date.now()}.zip`;
}

export class Chat extends Agent {
  async onMessage(connection, message) {
    if (message === 'export') {
      // Queued callbacks run later from the alarm loop and can't see this connection, so pass its id along.
      await this.queue('runExport', { connectionId: connection.id });
      connection.send('export started');
      return;
    }
    connection.send(`echo: ${message}`);
  }

  async runExport({ connectionId }) {
    const url = await buildExport(this.name);
    // The client may have disconnected while the export was building.
    this.getConnection(connectionId)?.send(`export ready: ${url}`);
  }
}

export default {
  async fetch(request, env) {
    return (await routeAgentRequest(request, env)) ?? new Response('Not found', { status: 404 });
  },
};

