export class Report extends Agent {
  initialState = { topic: null, report: null, generatedAt: null };

  async generate(topic) {
    const report = `Report on ${topic}: (placeholder)`;
    this.setState({ topic, report, generatedAt: new Date().toISOString() });
    return report;
  }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname === '/reports' && request.method === 'POST') {
      let body;
      try {
        body = await request.json();
      } catch {
        return Response.json({ error: 'Invalid JSON body' }, { status: 400 });
      }
      const topic = body?.topic;
      if (typeof topic !== 'string' || topic.trim() === '') {
        return Response.json({ error: '`topic` must be a non-empty string' }, { status: 400 });
      }

      // A fresh unique name per POST gives a new, separate Report instance.
      // The name (not the raw Durable Object id) is the handle: reach this
      // instance again later with getAgentByName(env.Report, id).
      const id = crypto.randomUUID();
      const report = await (await getAgentByName(env.Report, id)).generate(topic);
      return Response.json({ id, report });
    }

    return (await routeAgentRequest(request, env)) ?? new Response('Not found', { status: 404 });
  },
};

import { Agent, routeAgentRequest } from 'agents';
import { createSlackGateway, postSlackMessage } from './slack.js';

export class Chat extends Agent {
  async onMessage(connection, message) {
    connection.send(`echo: ${message}`);
  }

  // Called by the Slack ChannelGateway over RPC with an already verified event.
  async receive(event, origin) {
    if (event.type !== 'message') return;

    // Slack redelivers events it thinks timed out; eventId is stable across retries.
    this.sql`CREATE TABLE IF NOT EXISTS slack_events (id TEXT PRIMARY KEY)`;
    if (this.sql`SELECT id FROM slack_events WHERE id = ${event.eventId}`.length > 0) return;

    const text = event.message.parts
      .filter((part) => part.type === 'text')
      .map((part) => part.text)
      .join('\n')
      .replace(/<@[A-Z0-9]+>\s*/g, '') // drop the bot @mention from app_mention events
      .trim();

    await postSlackMessage(this.env.SLACK_BOT_TOKEN, origin.surface, `echo: ${text}`);
    this.sql`INSERT OR IGNORE INTO slack_events (id) VALUES (${event.eventId})`;
  }
}

export default {
  async fetch(request, env) {
    if (new URL(request.url).pathname === '/webhooks/slack') {
      return (await createSlackGateway(env).fetch(request)) ?? new Response('Not found', { status: 404 });
    }
    return (await routeAgentRequest(request, env)) ?? new Response('Not found', { status: 404 });
  },
};

